Item.method_code:
const keyedname = aras.getKeyedNameEx(item);
const { itemTypeName, itemId } = options;
const isNew = ArasModules.item.isNew(itemTypeName, itemId);
const cssStyle = 'aras-toolbar__title' + (isNew ? ' aras-toolbar__title_italic' : ' aras-toolbar__title-view');
const tooltip = isNew ? keyedname : aras.getResource('', 'toolbar.title_item_view.toltip', keyedname);

return {
	type: 'text',
	label: keyedname,
	cssClass: cssStyle,
	tooltip_template: tooltip,
};
